import os
from google.cloud import documentai_v1 as documentai
from google.cloud.documentai_v1.types import document

def normalize_expense_document(file_path):
    project_id = "YOUR_PROJECT_ID"
    location = "YOUR_PROCESSOR_LOCATION"
    processor_id = "YOUR_PROCESSOR_ID"

    client = documentai.DocumentProcessorServiceClient()

    resource_name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as image:
        image_content = image.read()

    document = {
        "content": image_content,
        "mime_type": "application/pdf",
    }
    request = documentai.ProcessDocumentRequest(
        name=resource_name,
        raw_document=document,
    )

    result = client.process_document(request=request)
    document = result.document

    normalized_expense = {
        "vendor_name": document.text,
        "purchase_date": None,
        "total_amount": None,
        "line_items": []
    }

    for entity in document.entities:
        if entity.type_ == "VENDOR_NAME":
            normalized_expense["vendor_name"] = entity.text
        elif entity.type_ == "TRANSACTION_DATE":
            normalized_expense["purchase_date"] = entity.text
        elif entity.type_ == "TOTAL":
            normalized_expense["total_amount"] = entity.text
        elif entity.type_ == "LINE_ITEM":
            line_item = {
                "description": None,
                "quantity": None,
                "unit_price": None,
                "amount": None
            }
            for property in entity.properties:
                if property.type_ == "DESCRIPTION":
                    line_item["description"] = property.text
                elif property.type_ == "QUANTITY":
                    line_item["quantity"] = property.text
                elif property.type_ == "UNIT_PRICE":
                    line_item["unit_price"] = property.text
                elif property.type_ == "AMOUNT":
                    line_item["amount"] = property.text
            normalized_expense["line_items"].append(line_item)

    return normalized_expense
